def transform(grid):
    h, w = len(grid), len(grid[0])
    vals = [row[0] for row in grid]

    # These stripe patterns repeat vertically. Find the shortest period
    # consistent with every colored row, and extend that pattern through
    # the blank rows.
    period = None
    for p in range(1, h + 1):
        residues = {}
        ok = True
        for i, v in enumerate(vals):
            if v:
                r = i % p
                if r in residues and residues[r] != v:
                    ok = False
                    break
                residues[r] = v
        if ok:
            period = p
            break

    # Fill missing residues by interpolating between known entries around
    # the repeating cycle.
    known = {i % period: v for i, v in enumerate(vals) if v}
    out = []
    for i in range(h):
        r = i % period
        if r in known:
            out.append(known[r])
        else:
            before = min(known, key=lambda k: (r - k) % period)
            out.append(known[before])
    return [[v] * w for v in out]
